from fastapi import FastAPI, HTTPException
from fastapi.responses import HTMLResponse

def create_app(db):
    app=FastAPI(title='Hazard Hunt November Automator')
    @app.get('/api/state')
    async def state(): return await db.summary()
    @app.post('/api/control/{value}')
    async def control(value:str):
        if value not in ('paused','running','shutdown'): raise HTTPException(status_code=400,detail='Expected paused, running, or shutdown')
        await db.set_control('execution',value)
        if value=='running': await db.resume_paused()
        return {'control':value,'scope':'Hazard Hunt November'}
    @app.get('/',response_class=HTMLResponse)
    async def index():
        return """<!doctype html><meta charset="utf-8"><title>Hazard Hunt November Automator</title>
<style>body{font:15px system-ui;margin:2rem;background:#101512;color:#e8eee9}table{border-collapse:collapse;width:100%;background:#1b231e;margin-bottom:1rem}td,th{padding:.6rem;border-bottom:1px solid #38443c;text-align:left;vertical-align:top}.cards{display:flex;gap:.5rem;flex-wrap:wrap}.card{padding:1rem;background:#1b231e;border-radius:8px}pre{white-space:pre-wrap;max-height:30rem;overflow:auto;background:#1b231e;padding:1rem}button{padding:.5rem 1rem;margin-right:.4rem}a{color:#c5ff00}.pill{padding:.2rem .5rem;border-radius:4px;background:#2a3a2e}.pending{background:#3a3a2a}.running{background:#2a3a2e}.completed{background:#1e3a2a}.failed{background:#3a1e1e}.paused{background:#2a2a3a}</style>
<h1>Hazard Hunt November</h1><p>Exact scope: <code>a3fae18d3d88e459ad14c613</code></p><p>Execution: <b id="control"></b></p>
<button onclick="setControl('paused')">Pause</button><button onclick="setControl('running')">Resume paused scenarios</button><button onclick="setControl('shutdown')">Graceful shutdown</button>
<div class="cards" id="cards"></div>
<h2>Eight worker slots</h2><table><thead><tr><th>Worker</th><th>Status</th><th>Scenario</th><th>Iteration</th><th>Last action</th></tr></thead><tbody id="agents"></tbody></table>
<h2>November scenarios</h2><table><thead><tr><th>Scenario</th><th>Status</th><th>Assigned worker</th><th>Action</th><th>Submission</th><th>Failure / intervention</th></tr></thead><tbody id="scenarios"></tbody></table>
<h2>Agent-to-agent interaction loops</h2>
<div class="cards" id="interaction-cards"></div>
<table><thead><tr><th>Session</th><th>Task</th><th>Status</th><th class="pill">Iter</th><th>Agent state</th><th>Latest req</th><th>Latest resp</th><th>Latency</th><th>Evaluator</th><th>Next action</th><th>Termination</th></tr></thead><tbody id="interactions"></tbody></table>
<h2>Interaction history (chronological)</h2><pre id="interaction-events"></pre>
<h2>Latest rendered observations</h2><pre id="obs"></pre><h2>Decisions, accepted/rejected actions, verification, and errors</h2><pre id="events"></pre>
<script>function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&','<':'<','>':'>','"':'"',"'":'''}[c]))}async function setControl(v){await fetch('/api/control/'+v,{method:'POST'});refresh()}async function refresh(){let d=await(await fetch('/api/state')).json(),c=d.counts;document.querySelector('#control').textContent=d.control;document.querySelector('#cards').innerHTML=['Eligible scenarios: '+d.scenario_total,'Completed: '+(c.completed||0),'Pending: '+(c.pending||0),'Active: '+((c.running||0)+(c.assigned||0)),'Failed: '+(c.failed||0),'Paused: '+(c.paused||0),'Manual intervention: '+(c.needs_manual_intervention||0),'Tokens: '+(d.usage.p+d.usage.c),'Estimated cost: '+Number(d.usage.cost).toFixed(4)].map(x=>'<div class="card">'+esc(x)+'</div>').join('');document.querySelector('#agents').innerHTML=Array.from({length:8},(_,i)=>{let a=d.agents.find(y=>y.agent_id==='agent-'+(i+1))||{agent_id:'agent-'+(i+1),status:'offline'};return '<tr><td>'+esc(a.agent_id)+'</td><td>'+esc(a.status)+'</td><td>'+esc(a.scenario_id||'—')+'</td><td>'+esc(a.iteration||0)+'</td><td>'+esc(a.last_action||'—')+'</td></tr>'}).join('');document.querySelector('#scenarios').innerHTML=d.scenarios.map(s=>'<tr><td><b>'+esc(s.name)+'</b><br><small>'+esc(s.scenario_id)+'</small></td><td>'+esc(s.status)+'</td><td>'+esc(s.agent_id||'—')+'</td><td>'+esc(s.last_action||'—')+'</td><td>'+esc(s.submission_state)+'</td><td>'+esc(s.failure||'—')+'</td></tr>').join('');let it=d.interactions||{};let sessions=it.sessions||[];let counts=it.counts||{};document.querySelector('#interaction-cards').innerHTML=['Active sessions: '+it.active,'Completed: '+it.completed,'Sessions: '+sessions.length].map(x=>'<div class="card">'+esc(x)+'</div>').join('');document.querySelector('#interactions').innerHTML=sessions.map(s=>{let status=s.current_status||'—';let cls=status;return '<tr><td><b>'+esc(s.session_id)+'</b></td><td>'+esc(s.task_id)+'</td><td class="pill '+cls+'">'+esc(status)+'</td><td class="pill">'+esc(s.current_iteration||0)+'/'+esc(s.maximum_iterations||0)+'</td><td>'+esc(s.agent_state||'—')+'</td><td>'+esc((s.latest_request&&s.latest_request.request_at)||'—')+'</td><td>'+esc((s.latest_response&&s.latest_response.response_at)||'—')+'</td><td>'+esc((s.latest_response&&s.latest_response.latency_ms)||'—')+' ms</td><td>'+esc((s.evaluator_decision&&s.evaluator_decision.decision)||'—')+'</td><td>'+esc((s.next_action||'').slice(0,80))+'</td><td>'+esc(s.termination_reason||'—')+'</td></tr>'}).join('');let iterEvents=it.iterations||[];document.querySelector('#interaction-events').textContent=iterEvents.map(x=>x.created_at+' iter:'+x.iteration+' stage:'+(x.stage||'—')+' status:'+(x.response_status||'—')+' latency:'+(x.latency_ms||'—')+'ms dec:'+(x.evaluator_decision&&x.evaluator_decision.decision||'—')+' next:'+(x.next_action||'—')).join('\\n');document.querySelector('#obs').textContent=d.scenarios.filter(s=>s.last_observation).map(s=>s.name+': '+s.last_observation).join('\\n\\n');document.querySelector('#events').textContent=d.events.map(x=>x.created_at+' '+x.kind+' '+(x.payload?.scenario_id||'')+' '+JSON.stringify(x.payload)).join('\\n')}refresh();setInterval(refresh,3000)</script>"""
    return app